package com.hms.notifications;
import java.util.Map; import org.springframework.http.MediaType; import org.springframework.web.client.RestClient;
public class WebhookNotificationProvider implements NotificationProvider {private final NotificationChannel channel;private final String endpoint;private final RestClient client;public WebhookNotificationProvider(NotificationChannel c,String e,RestClient.Builder b){channel=c;endpoint=e;client=b.build();} @Override public NotificationChannel channel(){return channel;} @Override public void send(NotificationMessage message){if(endpoint==null||endpoint.isBlank())throw new IllegalStateException("No webhook configured for "+channel);client.post().uri(endpoint).contentType(MediaType.APPLICATION_JSON).body(Map.of("channel",channel.name(),"recipient",message.getRecipient(),"templateKey",message.getTemplateKey(),"body",message.getBody())).retrieve().toBodilessEntity();}}
